package com.lendup.pagos.domain.model;
import static org.junit.jupiter.api.Assertions.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test;
class TransaccionEconomicaTest { private final Instant now=Instant.parse("2026-11-01T15:00:00Z");
  private TransaccionEconomica cobro(){return TransaccionEconomica.nueva(UUID.randomUUID(),null,null,null,TipoTransaccion.PAGO_TARIFA,new BigDecimal("20"),"PEN","MERCADO_PAGO",null,"clave-"+UUID.randomUUID(),now);}
  @Test void nuevaQuedaPendienteConMontoEscalado(){var t=cobro();assertEquals(EstadoTransaccion.PENDIENTE,t.estado());assertEquals(new BigDecimal("20.00"),t.monto());}
  @Test void aprobadoConfirmaYRegistraReferenciaYComision(){var t=cobro();assertTrue(t.aplicarResultadoCobro(ResultadoProveedor.APROBADO,"123",new BigDecimal("1.20"),now));assertEquals(EstadoTransaccion.CONFIRMADA,t.estado());assertEquals("123",t.referenciaProveedor());assertEquals(new BigDecimal("1.20"),t.comisionProveedor());assertNotNull(t.confirmadaEn());}
  @Test void confirmadaNoRetrocedeAnteNotificacionesTardias(){var t=cobro();t.aplicarResultadoCobro(ResultadoProveedor.APROBADO,"123",null,now);assertFalse(t.aplicarResultadoCobro(ResultadoProveedor.RECHAZADO,"124",null,now));assertEquals(EstadoTransaccion.CONFIRMADA,t.estado());}
  @Test void rechazadaPuedeAprobarseConOtroIntentoDelMismoCheckout(){var t=cobro();assertTrue(t.aplicarResultadoCobro(ResultadoProveedor.RECHAZADO,"1",null,now));assertEquals(EstadoTransaccion.RECHAZADA,t.estado());assertTrue(t.aplicarResultadoCobro(ResultadoProveedor.APROBADO,"2",null,now));assertEquals(EstadoTransaccion.CONFIRMADA,t.estado());}
  @Test void enProcesoNoCambiaElEstado(){var t=cobro();assertFalse(t.aplicarResultadoCobro(ResultadoProveedor.EN_PROCESO,"1",null,now));assertEquals(EstadoTransaccion.PENDIENTE,t.estado());}
  @Test void reembolsoSoloPasaDePendienteAConfirmadaOFallida(){var r=TransaccionEconomica.nueva(UUID.randomUUID(),null,null,null,TipoTransaccion.REEMBOLSO_TARIFA,BigDecimal.TEN,"PEN",null,"1","r-1",now);assertThrows(IllegalStateException.class,()->r.aplicarResultadoCobro(ResultadoProveedor.APROBADO,"1",null,now));r.fallar(now);assertEquals(EstadoTransaccion.FALLIDA,r.estado());assertThrows(IllegalStateException.class,()->r.confirmar(now));}
  @Test void exigeMontoPositivoYClave(){assertThrows(IllegalArgumentException.class,()->TransaccionEconomica.nueva(UUID.randomUUID(),null,null,null,TipoTransaccion.PAGO_TARIFA,BigDecimal.ZERO,"PEN",null,null,"k",now));assertThrows(IllegalArgumentException.class,()->TransaccionEconomica.nueva(UUID.randomUUID(),null,null,null,TipoTransaccion.PAGO_TARIFA,BigDecimal.ONE,"PEN",null,null," ",now));}
}
